package store

// This file registers all intentionally-permanent remoteUnsupported stubs into
// remoteUnsupportedAllowlist (declared in remote_unsupported_completeness_test.go).
//
// NEW FEATURE PATTERN: do NOT edit this file.  When your PR adds new Storage
// interface methods that are intentionally server-side only (remoteUnsupported),
// create a NEW file named remote_<feature>_completeness_test.go alongside your
// remote_<feature>.go and register only your entries there.  That way parallel
// feature branches never conflict on a shared registry file.
//
// See remote_unsupported_completeness_test.go for the statusIntentional /
// statusKnownGap constants and the remoteUnsupportedEntry type.

func init() {
	addRemoteUnsupported(map[string]remoteUnsupportedEntry{
		// --- Confirmed genuinely permanent ---

		"CountStaleMachineIdentitiesByProject": {statusIntentional,
			"the #393 grouped hygiene rollup query runs server-side only; documented in-code on the method itself"},

		"CreateNotification": {statusIntentional,
			"round 116 (#516): no self-scoped route an end-user credential could hit to create/escalate an arbitrary notification, and rightly so"},
		"HasUnreadNotification": {statusIntentional,
			"round 116 (#516): same reasoning as CreateNotification — no legitimate remote caller for this raw check"},
		"GetUnreadNotification": {statusIntentional,
			"round 116 (#516): same reasoning as CreateNotification"},
		"UpdateNotification": {statusIntentional,
			"round 116 (#516): same reasoning as CreateNotification — List/Count are proxied; raw mutation isn't a legitimate remote-caller need"},

		"WithAuditCheckpointLock": {statusIntentional,
			"round 119 audit: the entire audit-checkpoint feature (VerifyAuditChain, CreateAuditCheckpoint, LatestAuditCheckpoint, UpdateAuditCheckpointAnchor) is independently, unconditionally unimplemented for RemoteStorage too — the audit chain data lives at the hub. Bypassing just this lock would block nothing that isn't already blocked"},

		"SetSecretCertNotAfter": {statusIntentional,
			"round 119 audit: every caller (internal/core/certificate.go, certificate_expiry.go) invokes this as `_ = c.storage.SetSecretCertNotAfter(...)`, explicitly discarding the error — a best-effort ADR-056 compliance-posture cache write, never certificate inspection/rotation correctness"},
		"TryIncrementSecretReadCount": {statusIntentional,
			"round 119 audit: a best-effort, display-only per-version counter (caller discards the error). Real max-reads ENFORCEMENT is a separate call one line earlier, TryIncrementSecretNodeReadCount, which fails CLOSED under storage.type: remote — so a MaxReads-configured secret already denies the read before this stub is ever reached"},

		"CreateMFAChallenge": {statusIntentional,
			"round 119 audit: core.CreateMFAChallenge checks the RemoteMFAVerifier interface before ever calling storage.CreateMFAChallenge — under storage.type: remote this raw stub is never reached regardless of which second factor (TOTP or WebAuthn) follows; confirmed by TestLogin_RemoteStorage_ProxiesMFACredentialCheck"},
		"ConsumeMFARecoveryCode": {statusIntentional,
			"round 119 audit: sole caller is VerifyMFACredentials, same bypassed-branch reasoning as MarkTOTPStepUsed — recovery codes are only ever consumed at login, never during enrollment/management"},

		// Secret ACL (RBAC Phase 3)
		"ListAllUserRoleGrants":   {statusIntentional, "permission matrix is server-aggregated via GET /api/v1/rbac/permission-matrix; direct grant enumeration runs server-side"},
		"CreateOrUpdateSecretACL": {statusIntentional, "RBAC Phase 3 — no proxy route yet; ACL management is always server-side"},
		"ListSecretACLs":          {statusIntentional, "RBAC Phase 3 — no proxy route yet; ACL management is always server-side"},
		"ListSecretACLsByUser":    {statusIntentional, "RBAC Phase 3 — listing ACL-granted secrets for a user runs server-side in ListSecretsWithSharingInfo; the core function calls LocalStorage on the server, not RemoteStorage"},
		"GetSecretACL":            {statusIntentional, "RBAC Phase 3 — no proxy route yet; ACL management is always server-side"},
		"DeleteSecretACL":         {statusIntentional, "RBAC Phase 3 — no proxy route yet; ACL management is always server-side"},
		"GetSecretAncestors":      {statusIntentional, "RBAC Phase 3 — folder-ACL inheritance walk runs server-side; HasSecretACL uses ErrUnsupportedByBackend to skip the ancestor walk on remote callers"},

		"GetProjectUsageStats": {statusIntentional, "usage report queries run server-side; a future PR may add a /api/v1/system/usage proxy route"},

		// Anomaly config
		"GetAnomalyConfig":  {statusIntentional, "anomaly config is managed via /api/v1/admin/anomaly-config; raw storage call never reached from a remote-storage caller"},
		"SaveAnomalyConfig": {statusIntentional, "anomaly config is managed via /api/v1/admin/anomaly-config; raw storage call never reached from a remote-storage caller"},

		// Deployment-wide stats snapshots
		"SaveDeploymentStatsSnapshot":        {statusIntentional, "deployment-wide stats snapshots are saved server-side in GetDashboardStats; a remote caller never directly invokes this"},
		"GetPreviousDeploymentStatsSnapshot": {statusIntentional, "deployment-wide stats snapshot retrieval runs server-side; the trend is computed in core.GetDashboardStats, not in the CLI"},

		// Compliance posture snapshots
		"SaveCompliancePostureSnapshot":        {statusIntentional, "compliance posture snapshot writes are server-side only; GetCompliancePosture is a server-only admin endpoint with no remote caller"},
		"GetPreviousCompliancePostureSnapshot": {statusIntentional, "compliance posture snapshot reads are server-side only; same reasoning as SaveCompliancePostureSnapshot"},
		"ListCompliancePostureSnapshots":       {statusIntentional, "compliance posture snapshot list is server-side only; same reasoning as SaveCompliancePostureSnapshot"},

		// Temporal access schedules
		"GetSecretAccessSchedule":    {statusIntentional, "temporal schedule check runs server-side; schedule management routes are HTTP-proxied via secret_schedule.go"},
		"SetSecretAccessSchedule":    {statusIntentional, "temporal schedule check runs server-side; schedule management routes are HTTP-proxied via secret_schedule.go"},
		"DeleteSecretAccessSchedule": {statusIntentional, "temporal schedule check runs server-side; schedule management routes are HTTP-proxied via secret_schedule.go"},
	})
}
